#include "common.h"
#include "include_asm.h"

typedef int u128 __attribute__((mode(TI)));
extern unsigned char *create_part(int);
extern float random_float_between(float, float);
extern int scale_ticks(int);
extern int truncate_float_to_s32_r(float) __asm__("func_001FA898");
extern unsigned char *batalia_part_type49_textures;

// Spawns a particle of the given kind at pos with velocity vel.
void create_type_49_particle(void *pos, int kind, void *vel, float f) {
    float v[4];
    unsigned char *p;
    float *vp = v;
    *(u128 *)v = *(u128 *)vel;
    p = create_part(0x49);
    if (p != 0) {
        float s = 0.0f;
        int c = 0;
        switch (kind) {
        case 0:
            c = 0x20;
            s = 0.12f;
            random_float_between(0.25f, 0.25f);
            break;
        case 1:
            c = 0xD;
            s = 0.5f;
            random_float_between(1.0f, 1.0f);
            break;
        }
        *(short *)(p + 0xA) = scale_ticks(0x37);
        *(int *)(p + 4) = (c << 24) | 0xFFFFFF;
        p[9] = truncate_float_to_s32_r(4.0f) + 0x20;
        p[3] = 0x48;
        p[1] = 0;
        p[2] = batalia_part_type49_textures[kind];
        *(float *)(p + 0xC) = s * 210000.0f;
        p[8] = (int)random_float_between(0.0f, 360.0f);
        *(u128 *)(p + 0x10) = *(u128 *)pos;
        *(u128 *)(p + 0x20) = *(u128 *)vp;
        *(float *)(p + 0x2C) = f;
    }
}
